//! Size guard for the SFTP service futures that Tauri commands await.
//!
//! The command thunks generated by `generate_handler!` hold the awaited future
//! by value, several times over, in their own stack frame. A 64 KiB read buffer
//! kept alive across an `.await` once made those frames reach 800+ KiB and
//! overflowed the 1 MiB Windows thread stack as soon as a file mutation or
//! preview command was invoked. Large buffers must live on the heap.

use super::SftpSessionService;

/// Generous ceiling; the real futures are well under half of it.
const MAX_COMMAND_FUTURE_BYTES: usize = 24 * 1024;

fn future_bytes<A, B, Fut>(_method: impl FnOnce(A, B) -> Fut) -> usize {
    std::mem::size_of::<Fut>()
}

#[test]
fn sftp_command_futures_stay_small() {
    let sizes = [
        ("mutate_file", future_bytes(SftpSessionService::mutate_file)),
        (
            "preview_file",
            future_bytes(SftpSessionService::preview_file),
        ),
        ("tail_file", future_bytes(SftpSessionService::tail_file)),
        (
            "enqueue_transfer",
            future_bytes(SftpSessionService::enqueue_transfer),
        ),
    ];
    for (name, bytes) in sizes {
        assert!(
            bytes <= MAX_COMMAND_FUTURE_BYTES,
            "{name} future is {bytes} bytes; keep large buffers on the heap"
        );
    }
}
